export function parseSwapOnL1Instruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSwapOnL1Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      covenant: getNextAccount(),
      vault: getNextAccount(),
      creator: getNextAccount(),
      counterparty: getNextAccount(),
      escrowAuth: getNextAccount(),
      creatorVaultAta: getNextAccount(),
      counterpartyVaultAta: getNextAccount(),
      creatorPayoutAta: getNextAccount(),
      counterpartyPayoutAta: getNextAccount(),
      creatorMintAcct: getNextAccount(),
      counterpartyMintAcct: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      escrow: getNextAccount(),
    },
    data: getSwapOnL1InstructionDataDecoder().decode(instruction.data),
  };
}
